#!/usr/bin/env bash
# R13 look lane: per-chapter board-theme rooms + 2 premium rooms, ONE at a time via studio/bin/art.sh.
# usage: batch_r13.sh [name...] (FORCE=1 to redo). Then: python proc_r13.py
cd "$(dirname "$0")"
S="Art style (must match across the whole set): soft painterly 3D cartoon like a polished 2026 mobile game, smooth chunky rounded felt-toy shapes, clean soft shading and gentle gradients, NOT photorealistic, NOT flat vector, no outlines. One warm key light from the upper right, soft shadows falling down-left. Absolutely no text, no letters, no numbers, no logo, no watermark."
g(){ n=$1; shift; if [ -s "$n.png" ] && [ -z "$FORCE" ]; then echo "skip $n"; return; fi; echo "gen $n $(date +%T)"; timeout 600 /c/Users/Admin/Documents/Msjelly/studio/bin/art.sh "$(pwd -W)/$n.png" "$*" >/dev/null 2>&1; ls -la "$n.png" 2>&1 | awk '{print $5}'; }
W=("$@")
run(){ if [ ${#W[@]} -eq 0 ]; then return 0; fi; for w in "${W[@]}"; do [ "$w" = "$1" ] && return 0; done; return 1; }
BG="Portrait 2:3 full-bleed game background, NO magenta. Cozy cat cafe boarding room seen from slightly above, the same layout every time: a wall strip across the top 15 percent with a bay window at the upper right, a wide wooden table filling the lower 85 percent of the image, small props only in the four corners. The whole centre of the table is EMPTY, plain evenly lit wood planks, ready for a game board. No cats, no characters."
run brd_autumn && g brd_autumn "$BG Theme: a cosy autumn afternoon. A warm terracotta wall, the bay window shows orange and red maple trees with falling leaves, a few maple leaves near the table corners, a basket of red apples bottom-right, a small pumpkin bottom-left, a knitted mustard scarf top-left on a hook. Warm amber light, honey oak table. $S"
run brd_snow && g brd_snow "$BG Theme: a snowy winter morning. A pale powder-blue wall, the bay window shows soft falling snow over snowy pine trees, frost on the window corners, a steaming cocoa mug with marshmallows bottom-right, a small knitted red mitten pair bottom-left, a tiny pine garland top-left. Cool bright light with a warm touch, light birch wood table. $S"
run brd_lantern && g brd_lantern "$BG Theme: a lantern festival night. A deep plum wall, the bay window shows a dark indigo evening sky with glowing red and gold paper lanterns on strings, two small glowing paper lanterns bottom-right, a little teapot and mooncakes bottom-left, a lantern string across the top. Warm golden lantern glow, dark walnut table, still bright enough that the table centre reads clearly. $S"
run brd_beach && g brd_beach "$BG Theme: a sunny beach house. A light aqua wall, the bay window shows a turquoise sea, sand and a palm leaf, a straw sun hat and a starfish bottom-right, a small bucket and spade with seashells bottom-left, a little striped life ring top-left on the wall. Bright summer light, sun-bleached driftwood table. $S"
run brd_galaxy && g brd_galaxy "$BG Theme: a magical space observatory room. A deep midnight blue wall with tiny painted stars, the bay window shows a swirling purple and teal galaxy with a ringed planet, a small brass telescope bottom-left, a glowing crystal ball bottom-right, a crescent moon lamp top-left. Cool purple and teal glow with gold accents, a dark blue-violet wood table, still bright enough that the table centre reads clearly. $S"
run brd_candy && g brd_candy "$BG Theme: a candy sweet shop. A pastel pink wall with cream stripes, the bay window shows a candy land with lollipop trees and cotton candy clouds, a jar of colourful sweets bottom-right, a stack of macarons and a swirl lollipop bottom-left, a garland of wrapped sweets top-left. Soft pastel light, a light strawberry-cream painted wood table. $S"
echo done $(date +%T)
